    private void OnClick_ConsumeItem(object sender, RoutedEventArgs e)
    {
        _gameSession.UseCurrentConsumable();
    }

    private void OnClick_CraftItem(object sender, RoutedEventArgs e)
    {
        if (((FrameworkElement)sender).DataContext is Recipe recipe)
        {
            _gameSession.CraftItemUsing(recipe);
        }
    }

    private void InitializeUserInputActions()
    {
        _userInputAtions.Add(Key.W, () => _gameSession.MoveNorth());
        _userInputAtions.Add(Key.A, () => _gameSession.MoveWest());
        _userInputAtions.Add(Key.S, () => _gameSession.MoveSouth());
        _userInputAtions.Add(Key.D, () => _gameSession.MoveEast());
        _userInputAtions.Add(Key.K, () => _gameSession.AttackCurrentMonster());
        _userInputAtions.Add(Key.C, () => _gameSession.UseCurrentConsumable());
        _userInputAtions.Add(Key.I, () => SetTabFocusTo("InventoryTabItem"));
        _userInputAtions.Add(Key.Q, () => SetTabFocusTo("QuestTabItem"));
        _userInputAtions.Add(Key.R, () => SetTabFocusTo("RecipesTabItem"));
        _userInputAtions.Add(Key.T, () => OnClick_DisplayTradeScreen(this, new RoutedEventArgs()));
    }

    private void SetTabFocusTo(string tabName)
    {
        foreach(object item in PlayerDataTabControl.Items)
        {
            if(item is TabItem tabItem)
            {
                if(tabItem.Name == tabName)
                {
                    tabItem.IsSelected = true;
                    return;
                }
            }
        }
    }
    private void MainWindow_OnKeyDown(object sender, KeyEventArgs e)
    {
        if (_userInputAtions.ContainsKey(e.Key))
        {
            _userInputAtions[e.Key].Invoke();
        }
    }

    private void SetActiveGameSessionTo(GameSession gameSession)
    {
        _messageBroker.OnMessageRaised -= OnGameMessageRaised;
        _gameSession = gameSession;
        DataContext = _gameSession;

        GameMessages.Document.Blocks.Clear();

        _messageBroker.OnMessageRaised += OnGameMessageRaised;
    }
    private void StartNewGame_OnClick(object sender, RoutedEventArgs e)
    {
        Startup startup = new Startup();
        startup.Show();
        Close();
    }
    private void SaveGame_OnClick(object sender, RoutedEventArgs e)
    {
        SaveGame();
    }
    private void Exit_OnClick(object sender, RoutedEventArgs e)
    {
        Close();
    }
    private void MainWindow_OnClosing(object sender, CancelEventArgs e)
    {
        AskToSaveGame();
    }
    private void AskToSaveGame()
    {   
        YesNoWindow message = new YesNoWindow("Save Game", "Do you want to save you game?");
        message.Owner = GetWindow(this);
        message.ShowDialog();
        if (message.ClickedYes)
        {
            SaveGame();
        }
    }
    private void SaveGame()
    {
        SaveFileDialog saveFileDialog = new SaveFileDialog{InitialDirectory = AppDomain.CurrentDomain.BaseDirectory,
                                                           Filter = $"Saved games (*.{SAVE_GAME_FILE_EXTENSION}|*.{SAVE_GAME_FILE_EXTENSION})"};
        if(saveFileDialog.ShowDialog() == true)
        {
            SaveGameService.Save(new GameState(_gameSession.CurrentPlayer,
                                               _gameSession.CurrentLocation.XCoordinate,
                                               _gameSession.CurrentLocation.YCoordinate),
                                               saveFileDialog.FileName);
        }
    }
}

