using Microsoft.VisualStudio.TestTools.UnitTesting;
using Engine.Models;
using Engine.ViewModels;

namespace TestEngine.ViewModels
{
    [TestClass]
    public class TestGameSession
    {
        // Home is at (0, -1).
        private static GameSession CreateGameSession() =>
            new GameSession(TestPlayerBuilder.NewPlayer(), 0, -1);

        [TestMethod]
        public void TestCreateGameSession()
        {
            GameSession gameSession = CreateGameSession();

            Assert.IsNotNull(gameSession.CurrentPlayer);
            Assert.AreEqual("Home", gameSession.CurrentLocation.Name);
        }

        [TestMethod]
        public void TestPlayerMovesHomeAndIsCompletelyHealedOnKilled()
        {
            GameSession gameSession = CreateGameSession();

            gameSession.MoveNorth();
            Assert.AreEqual("Town Square", gameSession.CurrentLocation.Name);

            gameSession.CurrentPlayer.TakeDamage(999);

            Assert.AreEqual("Home", gameSession.CurrentLocation.Name);
            Assert.AreEqual(gameSession.CurrentPlayer.MaximumHitPoints, gameSession.CurrentPlayer.CurrentHitPoints);
        }

        [TestMethod]
        public void AMonsterThatKillsThePlayerOnArrivalSendsThemHome()
        {
            // A monster only attacks on arrival when it wins initiative, which is random,
            // so try repeatedly. With DEX 3 and 1 HP, most arrivals end in a first-strike kill.
            for (int attempt = 0; attempt < 50; attempt++)
            {
                // Start at the Town Gate (1, 0); the Spider Forest is to the east.
                GameSession gameSession = new GameSession(
                    TestPlayerBuilder.NewPlayer(currentHitPoints: 1, dexterity: 3), 1, 0);

                gameSession.MoveEast();

                if (gameSession.CurrentLocation.Name == "Home")
                {
                    Assert.IsFalse(gameSession.HasMonster, "the spider followed the player home");
                    Assert.AreEqual(gameSession.CurrentPlayer.MaximumHitPoints, gameSession.CurrentPlayer.CurrentHitPoints);
                    return;
                }
            }

            Assert.Inconclusive("the spider never killed the player on arrival in 50 tries");
        }
    }
}

