using System.Collections.ObjectModel;
using System.ComponentModel;
using System.Xml.Serialization;
using Newtonsoft.Json;

namespace Engine.Models;

public class Party
{
    private readonly ObservableCollection<Player> _members = new();

    public ReadOnlyObservableCollection<Player> Members {get;}

    public bool isWiped => _members.Count > 0 && _members.All(m => m.IsDead);
    public event EventHandler<Player>? OnMemberKilled;
    public event EventHandler? OnPartyWiped;

    public void AddMember(Player player)
    {
        player.OnKilled += OnMemberKilled;
        _members.Add(player);
    }
    public void RemoveMember(Player player)
    {
        player.OnKilled -= OnMemberKilled;
        _members.Remove(player);
    }
    public void CompleteHealAll()
    {
        foreach(Player character in _members)
        {
            character.CompleteHeal();
        }
    }
}

