using System;
using System.Security.Cryptography;
using Engine.Core;
using Engine.Models.EventArgs;
using Engine.Models;
using Engine.Models.Shared;

namespace Engine.Models;
public class Battle : IDisposable
{
    private readonly MessageBroker _messageBroker = MessageBroker.GetInstance();
    private readonly Player _player;
    private readonly Party _party;
    private readonly Monster _opponent;

    private enum Combatant
    {
        Player,
        Opponent
    }

    public event EventHandler<CombatVictoryEventArgs> OnCombatVictory;

    public Battle(Party party, Monster opponent)
    {
        _player = party.Members[0];
        _party = party;
        _opponent = opponent;

        _player.OnActionPerformed += OnCombatantActionPerformed;
        _opponent.OnActionPerformed += OnCombatantActionPerformed;
        _opponent.OnKilled += OnOpponentKilled;
    }

    // Not part of the constructor: if the opponent strikes first and kills the player, the
    // respawn disposes this battle through the caller's reference, so the caller must
    // already be holding the battle when the first attack happens.
    public void Start()
    {
        _messageBroker.RaiseMessage("");
        _messageBroker.RaiseMessage($"You see a {_opponent.Name} here");

        if(FirstAttacker(_player, _opponent) == Combatant.Opponent)
        {
            AttackPlayer();
        }
    }
    public void AttackOpponent()
    {
        if(_player.CurrentWeapon == null)
        {
            _messageBroker.RaiseMessage("You must select a weapon, to attack");
            return;
        }
        _player.UseCurrentWeaponOn(_opponent);
        if (_opponent.IsAlive)
        {
            AttackPlayer();
        }
        _player = _party[_party.IndexOf(_player)++];
    }
    public void Dispose()
    {
        _player.OnActionPerformed -= OnCombatantActionPerformed;
        _opponent.OnActionPerformed -= OnCombatantActionPerformed;
        _opponent.OnKilled -= OnOpponentKilled;
    }
    private void OnOpponentKilled(object sender, System.EventArgs e)
    {
        _messageBroker.RaiseMessage("");
        _messageBroker.RaiseMessage($"You defeated the {_opponent.Name}!");

        _messageBroker.RaiseMessage($"You receive {_opponent.RewardedExperiencePoints} experience points.");
        _player.AddExperience(_opponent.RewardedExperiencePoints);

        _messageBroker.RaiseMessage($"You receive {_opponent.Gold} gold.");
        _player.ReceiveGold(_opponent.Gold);

        foreach(GameItem gameItem in _opponent.Inventory.Items)
        {
            _messageBroker.RaiseMessage($"You receive one {gameItem.Name}.");
            _player.AddItemToInventory(gameItem);
        }

        OnCombatVictory?.Invoke(this, new CombatVictoryEventArgs());   
    }
    private void AttackPlayer()
    {
        _opponent.UseCurrentWeaponOn(_player);
    }
    private void OnCombatantActionPerformed(object sender, string result)
    {
        _messageBroker.RaiseMessage(result);
    }
    private static Combatant FirstAttacker(Player player, Monster opponent)
    {
        // Formula is: ((Dex(player)^2 - Dex(monster)^2)/10) + Random(-10/10)
        // For dexterity values from 3 to 18, this should produce an offset of +/- 41.5
        int playerDexterity = player.GetAttribute("DEX").ModifiedValue * player.GetAttribute("DEX").ModifiedValue;
        int opponentDexterity = opponent.GetAttribute("DEX").ModifiedValue * opponent.GetAttribute("DEX").ModifiedValue;
        decimal dexterityOffset = (playerDexterity - opponentDexterity) / 10m;
        int randomOffset = DiceService.Instance.Roll(20).Value - 10;
        decimal totalOffset = dexterityOffset + randomOffset;

        return DiceService.Instance.Roll(100).Value <= 50 + totalOffset
                    ? Combatant.Player
                    : Combatant.Opponent;
    }
}

content.text:
Diese Zeile hat mehrere Fehler, und es gibt ein Designproblem dahinter.

**Warum die Zeile nicht kompiliert:**

1. `Party` hat weder einen Indexer noch `IndexOf`. Beides gibt es nur auf `_party.Members`.
2. `++` funktioniert nur auf Variablen, nicht auf dem Rückgabewert einer Methode (Fehler CS1059). Selbst wenn es ginge: Das nachgestellte `++` liefert den **alten** Wert, du bekämst also denselben Spieler zurück. Du willst `+ 1`.
3. `_player` ist `readonly` ([Battle.cs:12](Engine.Models/Battle.cs#L12)) und darf nur im Konstruktor gesetzt werden.

**Was zur Laufzeit schiefgehen würde:**

4. Beim letzten Mitglied liefert `IndexOf + 1` einen Index hinter der Liste, das gibt eine `ArgumentOutOfRangeException`. Mit `% Count` fängst du wieder vorne an.
5. Tote Mitglieder würden auch an die Reihe kommen.
6. Im Konstruktor wird nur `Members[0]` bei `OnActionPerformed` angemeldet. Die Angriffe der anderen würden also keine Meldungen erzeugen. Melde alle Mitglieder an und in `Dispose` wieder ab.

So könnte es aussehen:

```csharp
private Player _player;   // ohne readonly

public Battle(Party party, Monster opponent)
{
    _party = party;
    _player = party.Members[0];
    _opponent = opponent;

    foreach (Player member in _party.Members)
    {
        member.OnActionPerformed += OnCombatantActionPerformed;
    }
    _opponent.OnActionPerformed += OnCombatantActionPerformed;
    _opponent.OnKilled += OnOpponentKilled;
}

public void AttackOpponent()
{
    ...
    _player.UseCurrentWeaponOn(_opponent);
    if (_opponent.IsAlive)
    {
        AttackPlayer();
        SelectNextLivingMember();
    }
}

public void Dispose()
{
    foreach (Player member in _party.Members)
    {
        member.OnActionPerformed -= OnCombatantActionPerformed;
    }
    _opponent.OnActionPerformed -= OnCombatantActionPerformed;
    _opponent.OnKilled -= OnOpponentKilled;
}

private void SelectNextLivingMember()
{
    int index = _party.Members.IndexOf(_player);
    for (int offset = 1; offset <= _party.Members.Count; offset++)
    {
        Player next = _party.Members[(index + offset) % _party.Members.Count];
        if (next.IsAlive)
        {
            _player = next;
            return;
        }
    }
}
```

Der Wechsel steht innerhalb von `if (_opponent.IsAlive)`. Ist das Monster tot, ist der Kampf vorbei und es muss niemand mehr drankommen.

**Das Designproblem:** Die UI zeigt `GameSession.CurrentPlayer` an. Die Waffenauswahl ist an `CurrentPlayer.CurrentWeapon` gebunden. Wechselt `Battle` intern den Spieler, bekommt `GameSession` das nicht mit:
- Auf dem Bildschirm steht Spieler A, angreifen tut aber Spieler B.
- Die Prüfung "You must select a weapon" bezieht sich auf B, obwohl du gerade die Waffe von A siehst.

Ich würde deshalb `GameSession` entscheiden lassen, wer dran ist, und `Battle` den Angreifer übergeben:

```csharp
// Battle
public void AttackOpponent(Player attacker) { ... }

// GameSession
public void AttackCurrentMonster()
{
    _currentBattle?.AttackOpponent(CurrentPlayer);
    CurrentPlayer = NextLivingMember();   // Party oder GameSession
}
```

Dann gibt es nur eine Stelle, an der festgelegt ist, wer aktiv ist, und UI und Kampf zeigen immer denselben Spieler. `SelectNextLivingMember` würde dann als `NextLivingMember(Player current)` in die `Party` wandern.

Soll ich das in dieser Form umbauen?

